"""Shipping, tax and order quotes. All amounts are in US dollars."""

from shop.cart import Cart
from shop.money import round_money

TAX_RATES: dict[str, float] = {
    "US-CA": 0.0725,
    "US-NY": 0.04,
    "EU-DE": 0.19,
    "IN-KA": 0.18,
}

SHIPPING_FLAT = 5.00
FREE_SHIPPING_THRESHOLD = 50.00

SMALL_ORDER_FEE = 1.50
SMALL_ORDER_THRESHOLD = 15.00


def shipping_for(subtotal: float) -> float:
    return 0.0 if subtotal >= FREE_SHIPPING_THRESHOLD else SHIPPING_FLAT


def fee_for(subtotal: float) -> float:
    return SMALL_ORDER_FEE if subtotal < SMALL_ORDER_THRESHOLD else 0.0


def tax_for(subtotal: float, region: str) -> float:
    if region not in TAX_RATES:
        raise ValueError(f"unsupported region: {region}")
    return round_money(subtotal * TAX_RATES[region])


def quote(cart: Cart, region: str) -> dict[str, float]:
    """Price breakdown for a cart: subtotal, shipping, tax (on the subtotal) and total."""
    subtotal = cart.subtotal()
    shipping = shipping_for(subtotal)
    tax = tax_for(subtotal, region)
    return {
        "subtotal": subtotal,
        "shipping": shipping,
        "tax": tax,
        "total": round_money(subtotal + shipping + tax),
    }

import pytest

from shop.cart import Cart
from shop.pricing import quote, shipping_for, tax_for


def test_flat_shipping_below_threshold():
    assert shipping_for(49.99) == 5.00


def test_free_shipping_at_threshold():
    assert shipping_for(50.00) == 0.0


def test_tax_is_rounded_to_cents():
    assert tax_for(39.98, "US-CA") == 2.90
    assert tax_for(9.95, "EU-DE") == 1.89


def test_unsupported_region():
    with pytest.raises(ValueError):
        tax_for(10.0, "XX-00")


def test_quote_breakdown():
    cart = Cart()
    cart.add("TEE-01", 2)
    assert quote(cart, "US-CA") == {
        "subtotal": 39.98,
        "shipping": 5.00,
        "fee": 0.0,
        "tax": 2.90,
        "total": 47.88,
    }


def test_quote_with_free_shipping():
    cart = Cart()
    cart.add("MUG-01", 4)
    q = quote(cart, "US-NY")
    assert q["shipping"] == 0.0
    assert q["total"] == 52.00


def test_small_order_fee_below_threshold():
    assert fee_for(14.99) == 1.50


def test_no_small_order_fee_at_threshold():
    assert fee_for(15.00) == 0.0


def test_quote_with_small_order_fee():
    cart = Cart()
    cart.add("BAG-01")
    assert quote(cart, "EU-DE") == {
        "subtotal": 9.95,
        "shipping": 5.00,
        "fee": 1.50,
        "tax": 1.89,  # tax is on the subtotal only, not the fee
        "total": 18.34,
    }

